parameters.jsCode:
const output = $input.first().json.output;

try {
  const cleaned = output.replace(/```json\n?|\n?```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  return [{ json: parsed }];
} catch(e) {
  return [{ json: {
    reply: output,
    qualification_status: "in_progress",
    action: "none",
    lead: { name: null, budget: null, location: null, timeline: null, purpose: null }
  }}];
}

